CREATE OR REPLACE FUNCTION private_app.training_journey_financial_access_v1(p_enrollment_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e academy.enrollments%rowtype; f jsonb;
begin
 select * into e from academy.enrollments where id=p_enrollment_id;
 if e.id is null then raise exception 'enrollment_not_found'; end if;
 f:=private_app.training_journey_handoff_finance_v1(e.handoff_id,p_as_of);
 if not exists(select 1 from academy.registration_handoffs h where h.tenant_id=e.tenant_id and h.id=e.handoff_id and h.status='completed'
  and (h.payment_status='verified' or private_app.training_journey_credit_authorized_v1(h.id,p_as_of))) then
  f:=f||jsonb_build_object('trainingAllowed',false,'certificationAllowed',false,
   'reasonCodes',coalesce(f->'reasonCodes','[]')||jsonb_build_array('admission_confirmation_required'));
 end if;
 if e.status not in ('confirmed','active','completed') then
  f:=f||jsonb_build_object('trainingAllowed',false,'certificationAllowed',false,
   'reasonCodes',coalesce(f->'reasonCodes','[]')||jsonb_build_array('enrollment_inactive'));
 end if;
 if e.metadata->>'trainingJourneyDeferred'='true' then
  f:=f||jsonb_build_object('trainingAllowed',false,'certificationAllowed',false,
   'reasonCodes',coalesce(f->'reasonCodes','[]')||jsonb_build_array('enrollment_deferred'));
 end if;
 return f;
end $function$

CREATE OR REPLACE FUNCTION private_app.validate_enrollment_course_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run academy.course_runs%rowtype;
  v_enrolled_count integer;
  v_lifecycle_update boolean := false;
begin
  if new.status not in ('confirmed', 'active', 'completed') then
    return new;
  end if;

  select *
  into v_run
  from academy.course_runs run
  where run.id = new.course_run_id
  for update;

  if v_run.id is null
     or v_run.tenant_id <> new.tenant_id
     or v_run.course_id <> new.course_id then
    raise exception 'invalid_course_run';
  end if;

  if tg_op = 'UPDATE' then
    v_lifecycle_update :=
      new.course_run_id is not distinct from old.course_run_id
      and new.course_id is not distinct from old.course_id
      and new.tenant_id is not distinct from old.tenant_id
      and new.status in ('active', 'completed');
  end if;

  if v_lifecycle_update then
    if v_run.status not in ('open', 'in_progress', 'completed') then
      raise exception 'course_run_not_operational';
    end if;
    return new;
  end if;

  if v_run.status <> 'open' then
    raise exception 'course_run_not_open';
  end if;
  if v_run.registration_opens_at is not null
     and now() < v_run.registration_opens_at then
    raise exception 'course_run_registration_not_started';
  end if;
  if v_run.registration_closes_at is not null
     and now() > v_run.registration_closes_at then
    raise exception 'course_run_registration_closed';
  end if;

  select count(*)::integer
  into v_enrolled_count
  from academy.enrollments enrollment
  where enrollment.course_run_id = v_run.id
    and enrollment.status in ('confirmed', 'active', 'completed')
    and enrollment.id <> new.id;

  if v_run.capacity is not null
     and v_enrolled_count >= v_run.capacity then
    raise exception 'course_run_full';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private_app.validate_handoff_course_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run academy.course_runs%rowtype;
  v_enrolled_count integer;
begin
  if new.course_run_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.course_run_id is not distinct from old.course_run_id
     and new.course_id is not distinct from old.course_id
     and new.tenant_id is not distinct from old.tenant_id then
    return new;
  end if;

  select *
  into v_run
  from academy.course_runs run
  where run.id = new.course_run_id
  for update;

  if v_run.id is null
     or v_run.tenant_id <> new.tenant_id
     or v_run.course_id <> new.course_id then
    raise exception 'invalid_course_run';
  end if;
  if v_run.status <> 'open' then
    raise exception 'course_run_not_open';
  end if;
  if v_run.registration_opens_at is not null
     and now() < v_run.registration_opens_at then
    raise exception 'course_run_registration_not_started';
  end if;
  if v_run.registration_closes_at is not null
     and now() > v_run.registration_closes_at then
    raise exception 'course_run_registration_closed';
  end if;

  select count(*)::integer
  into v_enrolled_count
  from academy.enrollments enrollment
  where enrollment.course_run_id = v_run.id
    and enrollment.status in ('confirmed', 'active', 'completed');

  if v_run.capacity is not null
     and v_enrolled_count >= v_run.capacity then
    raise exception 'course_run_full';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.v1_tenant_accounting_action(p_slug text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant core.tenants%rowtype;
  v_actor uuid;
  v_required_permission text;
  v_command_id uuid;
  v_request_hash text:=md5(coalesce(p_payload,'{}'::jsonb)::text);
  v_existing accounting_core.commands%rowtype;
  v_result jsonb;
  v_account accounting_core.customer_accounts%rowtype;
  v_document accounting_core.sales_documents%rowtype;
  v_parent accounting_core.sales_documents%rowtype;
  v_payment accounting_core.payments%rowtype;
  v_refund accounting_core.refunds%rowtype;
  v_receipt accounting_core.receipts%rowtype;
  v_contact sales_core.contacts%rowtype;
  v_profile accounting_core.tenant_profiles%rowtype;
  v_id uuid;
  v_document_type text;
  v_target_status text;
  v_line jsonb;
  v_lines jsonb;
  v_position integer:=0;
  v_quantity numeric(12,3);
  v_unit bigint;
  v_subtotal bigint;
  v_discount bigint;
  v_tax_rate integer;
  v_tax bigint;
  v_total bigint;
  v_sum_subtotal bigint:=0;
  v_sum_discount bigint:=0;
  v_sum_tax bigint:=0;
  v_sum_total bigint:=0;
  v_amount bigint;
  v_allocated bigint;
  v_refunded bigint;
  v_prefix text;
  v_status text;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if jsonb_typeof(coalesce(p_payload,'{}'::jsonb))<>'object' then
    raise exception 'accounting_payload_invalid';
  end if;
  select * into v_tenant from core.tenants
  where slug=p_slug and status in ('trial','active') limit 1;
  if v_tenant.id is null then raise exception 'tenant_not_found'; end if;

  v_required_permission:=case p_action
    when 'create_customer_account' then 'tenant.accounting.customers.write'
    when 'update_customer_account' then 'tenant.accounting.customers.write'
    when 'create_document' then case when p_payload->>'documentType'='quote'
      then 'tenant.accounting.quotes.write' else 'tenant.accounting.invoices.write' end
    when 'update_document' then case when p_payload->>'documentType'='quote'
      then 'tenant.accounting.quotes.write' else 'tenant.accounting.invoices.write' end
    when 'issue_document' then 'tenant.accounting.read'
    when 'cancel_document' then 'tenant.accounting.read'
    when 'record_payment' then 'tenant.accounting.payments.record'
    when 'verify_payment' then 'tenant.accounting.payments.approve'
    when 'allocate_payment' then 'tenant.accounting.payments.approve'
    when 'issue_receipt' then 'tenant.accounting.payments.approve'
    when 'create_schedule' then 'tenant.accounting.invoices.write'
    when 'record_collection_action' then 'tenant.accounting.read'
    when 'request_refund' then 'tenant.accounting.refunds.request'
    when 'approve_refund' then 'tenant.accounting.refunds.approve'
    when 'reject_refund' then 'tenant.accounting.refunds.approve'
    when 'complete_refund' then 'tenant.accounting.refunds.approve'
    when 'save_settings' then 'tenant.accounting.settings.manage'
    when 'import_handoff_payment' then 'tenant.accounting.payments.approve'
    else null end;
  if v_required_permission is null then raise exception 'accounting_action_invalid'; end if;
  if not private_app.has_accounting_permission(v_tenant.id,v_required_permission) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  if p_action in ('issue_document','cancel_document') then
    select document_type into v_document_type
    from accounting_core.sales_documents
    where tenant_id=v_tenant.id and id=(p_payload->>'documentId')::uuid;
    if v_document_type is null then raise exception 'document_not_found'; end if;
    if v_document_type='quote' and not private_app.has_accounting_permission(
      v_tenant.id,'tenant.accounting.quotes.write'
    ) then raise exception 'forbidden' using errcode='42501'; end if;
    if v_document_type<>'quote' and not private_app.has_accounting_permission(
      v_tenant.id,case when p_action='issue_document'
        then 'tenant.accounting.invoices.issue' else 'tenant.accounting.invoices.write' end
    ) then raise exception 'forbidden' using errcode='42501'; end if;
  end if;
  v_actor:=private_app.current_subject_id();
  begin v_command_id:=nullif(p_payload->>'commandId','')::uuid;
  exception when invalid_text_representation then raise exception 'command_id_invalid'; end;
  if v_command_id is not null then
    select * into v_existing from accounting_core.commands
    where tenant_id=v_tenant.id and command_id=v_command_id;
    if v_existing.command_id is not null then
      if v_existing.action<>p_action or v_existing.request_hash<>v_request_hash then
        raise exception 'command_id_reused_with_different_payload';
      end if;
      return v_existing.response;
    end if;
  end if;

  select * into v_profile from accounting_core.tenant_profiles
  where tenant_id=v_tenant.id;

  if p_action='save_settings' then
    insert into accounting_core.tenant_profiles(
      tenant_id,legal_name_ar,commercial_registration_number,vat_number,
      tax_registered,base_currency,timezone,default_payment_terms_days,
      default_tax_rate_bps,quote_prefix,invoice_prefix,credit_note_prefix,
      debit_note_prefix,receipt_prefix,auto_import_verified_admissions,
      created_by_subject_id,updated_by_subject_id
    ) values(
      v_tenant.id,nullif(btrim(p_payload->>'legalNameAr'),''),
      nullif(btrim(p_payload->>'commercialRegistrationNumber'),''),
      nullif(btrim(p_payload->>'vatNumber'),''),
      coalesce((p_payload->>'taxRegistered')::boolean,false),
      coalesce(nullif(upper(btrim(p_payload->>'baseCurrency')),''),'SAR'),
      coalesce(nullif(btrim(p_payload->>'timezone'),''),'Asia/Riyadh'),
      coalesce((p_payload->>'defaultPaymentTermsDays')::integer,0),
      coalesce((p_payload->>'defaultTaxRateBps')::integer,1500),
      coalesce(nullif(upper(btrim(p_payload->>'quotePrefix')),''),'Q'),
      coalesce(nullif(upper(btrim(p_payload->>'invoicePrefix')),''),'INV'),
      coalesce(nullif(upper(btrim(p_payload->>'creditNotePrefix')),''),'CN'),
      coalesce(nullif(upper(btrim(p_payload->>'debitNotePrefix')),''),'DN'),
      coalesce(nullif(upper(btrim(p_payload->>'receiptPrefix')),''),'REC'),
      coalesce((p_payload->>'autoImportVerifiedAdmissions')::boolean,false),
      v_actor,v_actor
    ) on conflict(tenant_id) do update set
      legal_name_ar=excluded.legal_name_ar,
      commercial_registration_number=excluded.commercial_registration_number,
      vat_number=excluded.vat_number,tax_registered=excluded.tax_registered,
      base_currency=excluded.base_currency,timezone=excluded.timezone,
      default_payment_terms_days=excluded.default_payment_terms_days,
      default_tax_rate_bps=excluded.default_tax_rate_bps,
      quote_prefix=excluded.quote_prefix,invoice_prefix=excluded.invoice_prefix,
      credit_note_prefix=excluded.credit_note_prefix,
      debit_note_prefix=excluded.debit_note_prefix,receipt_prefix=excluded.receipt_prefix,
      auto_import_verified_admissions=excluded.auto_import_verified_admissions,
      updated_by_subject_id=excluded.updated_by_subject_id,updated_at=now();
    v_result:=jsonb_build_object('success',true,'action',p_action);

  elsif p_action in ('create_customer_account','update_customer_account') then
    if p_action='create_customer_account' then
      if nullif(p_payload->>'contactId','') is not null then
        select * into v_contact from sales_core.contacts
        where tenant_id=v_tenant.id and id=(p_payload->>'contactId')::uuid;
        if v_contact.id is null then raise exception 'contact_not_found'; end if;
      end if;
      insert into accounting_core.customer_accounts(
        tenant_id,contact_id,account_number,display_name,organization_name,
        billing_email,billing_phone,tax_number,billing_address,
        payment_terms_days,credit_limit_minor,status,notes,
        created_by_subject_id,updated_by_subject_id
      ) values(
        v_tenant.id,v_contact.id,
        private_app.accounting_next_number(v_tenant.id,'customer',current_date,'CUS'),
        coalesce(nullif(btrim(p_payload->>'displayName'),''),v_contact.full_name),
        coalesce(nullif(btrim(p_payload->>'organizationName'),''),v_contact.organization_name),
        coalesce(nullif(btrim(p_payload->>'billingEmail'),''),v_contact.email),
        coalesce(nullif(btrim(p_payload->>'billingPhone'),''),v_contact.phone),
        nullif(btrim(p_payload->>'taxNumber'),''),nullif(btrim(p_payload->>'billingAddress'),''),
        coalesce((p_payload->>'paymentTermsDays')::integer,v_profile.default_payment_terms_days,0),
        (p_payload->>'creditLimitMinor')::bigint,'active',nullif(btrim(p_payload->>'notes'),''),
        v_actor,v_actor
      ) returning * into v_account;
    else
      update accounting_core.customer_accounts set
        display_name=coalesce(nullif(btrim(p_payload->>'displayName'),''),display_name),
        organization_name=case when p_payload?'organizationName' then nullif(btrim(p_payload->>'organizationName'),'') else organization_name end,
        billing_email=case when p_payload?'billingEmail' then nullif(btrim(p_payload->>'billingEmail'),'') else billing_email end,
        billing_phone=case when p_payload?'billingPhone' then nullif(btrim(p_payload->>'billingPhone'),'') else billing_phone end,
        tax_number=case when p_payload?'taxNumber' then nullif(btrim(p_payload->>'taxNumber'),'') else tax_number end,
        billing_address=case when p_payload?'billingAddress' then nullif(btrim(p_payload->>'billingAddress'),'') else billing_address end,
        payment_terms_days=coalesce((p_payload->>'paymentTermsDays')::integer,payment_terms_days),
        credit_limit_minor=case when p_payload?'creditLimitMinor' then (p_payload->>'creditLimitMinor')::bigint else credit_limit_minor end,
        status=coalesce(nullif(p_payload->>'status',''),status),
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else notes end,
        updated_by_subject_id=v_actor,updated_at=now()
      where tenant_id=v_tenant.id and id=(p_payload->>'accountId')::uuid
      returning * into v_account;
      if v_account.id is null then raise exception 'customer_account_not_found'; end if;
    end if;
    v_result:=jsonb_build_object('success',true,'action',p_action,'accountId',v_account.id);

  elsif p_action in ('create_document','update_document') then
    v_document_type:=coalesce(nullif(p_payload->>'documentType',''),'invoice');
    if v_document_type not in ('quote','invoice','credit_note','debit_note') then
      raise exception 'document_type_invalid';
    end if;
    if jsonb_typeof(p_payload->'lines')<>'array' or jsonb_array_length(p_payload->'lines')=0
       or jsonb_array_length(p_payload->'lines')>100 then raise exception 'document_lines_required'; end if;
    select * into v_account from accounting_core.customer_accounts
    where tenant_id=v_tenant.id and id=(p_payload->>'customerAccountId')::uuid and status<>'closed';
    if v_account.id is null then raise exception 'customer_account_not_found'; end if;
    if p_action='update_document' then
      select * into v_document from accounting_core.sales_documents
      where tenant_id=v_tenant.id and id=(p_payload->>'documentId')::uuid and status='draft'
      for update;
      if v_document.id is null then raise exception 'document_not_editable'; end if;
      if v_document.document_type<>v_document_type then raise exception 'document_type_immutable'; end if;
      delete from accounting_core.sales_document_lines
      where tenant_id=v_tenant.id and document_id=v_document.id;
    else
      if nullif(p_payload->>'parentDocumentId','') is not null then
        select * into v_parent from accounting_core.sales_documents
        where tenant_id=v_tenant.id and id=(p_payload->>'parentDocumentId')::uuid;
        if v_parent.id is null then raise exception 'parent_document_not_found'; end if;
        if v_document_type='invoice' and (v_parent.document_type<>'quote' or v_parent.status<>'accepted') then
          raise exception 'quote_not_convertible';
        end if;
      end if;
      v_prefix:=case v_document_type
        when 'quote' then coalesce(v_profile.quote_prefix,'Q')
        when 'invoice' then coalesce(v_profile.invoice_prefix,'INV')
        when 'credit_note' then coalesce(v_profile.credit_note_prefix,'CN')
        else coalesce(v_profile.debit_note_prefix,'DN') end;
      insert into accounting_core.sales_documents(
        tenant_id,document_type,document_number,status,customer_account_id,
        contact_id,parent_document_id,source_type,source_id,issue_date,
        valid_until,due_date,currency,customer_name_snapshot,
        customer_tax_number_snapshot,customer_email_snapshot,
        customer_phone_snapshot,customer_address_snapshot,notes,terms,
        metadata,created_by_subject_id,updated_by_subject_id
      ) values(
        v_tenant.id,v_document_type,
        private_app.accounting_next_number(v_tenant.id,v_document_type,
          coalesce((p_payload->>'issueDate')::date,current_date),v_prefix),
        'draft',v_account.id,v_account.contact_id,v_parent.id,
        nullif(p_payload->>'sourceType',''),nullif(p_payload->>'sourceId',''),
        coalesce((p_payload->>'issueDate')::date,current_date),
        (p_payload->>'validUntil')::date,
        coalesce((p_payload->>'dueDate')::date,
          case when v_document_type in ('invoice','debit_note') then current_date+v_account.payment_terms_days else null end),
        coalesce(nullif(upper(p_payload->>'currency'),''),v_profile.base_currency,'SAR'),
        v_account.display_name,v_account.tax_number,v_account.billing_email,
        v_account.billing_phone,v_account.billing_address,
        nullif(btrim(p_payload->>'notes'),''),nullif(btrim(p_payload->>'terms'),''),
        coalesce(p_payload->'metadata','{}'::jsonb),v_actor,v_actor
      ) returning * into v_document;
    end if;
    v_lines:=p_payload->'lines';
    v_position:=0;v_sum_subtotal:=0;v_sum_discount:=0;v_sum_tax:=0;v_sum_total:=0;
    for v_line in select value from jsonb_array_elements(v_lines) loop
      v_position:=v_position+1;
      v_quantity:=coalesce((v_line->>'quantity')::numeric,1);
      v_unit:=coalesce((v_line->>'unitAmountMinor')::bigint,0);
      v_subtotal:=round(v_quantity*v_unit)::bigint;
      v_discount:=coalesce((v_line->>'discountMinor')::bigint,0);
      v_tax_rate:=case when coalesce(v_line->>'taxCategory','standard')='standard'
        then coalesce((v_line->>'taxRateBps')::integer,v_profile.default_tax_rate_bps,1500) else 0 end;
      if v_quantity<=0 or v_unit<0 or v_discount<0 or v_discount>v_subtotal then
        raise exception 'document_line_invalid';
      end if;
      v_tax:=case when coalesce(v_line->>'taxCategory','standard')='standard'
        then round((v_subtotal-v_discount)::numeric*v_tax_rate/10000)::bigint else 0 end;
      v_total:=v_subtotal-v_discount+v_tax;
      insert into accounting_core.sales_document_lines(
        tenant_id,document_id,position,item_type,source_id,description,
        quantity,unit_amount_minor,subtotal_minor,discount_minor,
        tax_category,tax_rate_bps,tax_minor,total_minor,metadata
      ) values(
        v_tenant.id,v_document.id,v_position,
        coalesce(nullif(v_line->>'itemType',''),'service'),
        nullif(v_line->>'sourceId',''),
        btrim(v_line->>'description'),v_quantity,v_unit,v_subtotal,v_discount,
        coalesce(nullif(v_line->>'taxCategory',''),'standard'),v_tax_rate,v_tax,v_total,
        coalesce(v_line->'metadata','{}'::jsonb)
      );
      v_sum_subtotal:=v_sum_subtotal+v_subtotal;
      v_sum_discount:=v_sum_discount+v_discount;
      v_sum_tax:=v_sum_tax+v_tax;
      v_sum_total:=v_sum_total+v_total;
    end loop;
    update accounting_core.sales_documents set
      customer_account_id=v_account.id,contact_id=v_account.contact_id,
      issue_date=coalesce((p_payload->>'issueDate')::date,issue_date),
      valid_until=(p_payload->>'validUntil')::date,
      due_date=coalesce((p_payload->>'dueDate')::date,due_date),
      customer_name_snapshot=v_account.display_name,
      customer_tax_number_snapshot=v_account.tax_number,
      customer_email_snapshot=v_account.billing_email,
      customer_phone_snapshot=v_account.billing_phone,
      customer_address_snapshot=v_account.billing_address,
      subtotal_minor=v_sum_subtotal,discount_minor=v_sum_discount,
      tax_minor=v_sum_tax,total_minor=v_sum_total,
      notes=nullif(btrim(p_payload->>'notes'),''),
      terms=nullif(btrim(p_payload->>'terms'),''),
      updated_by_subject_id=v_actor,updated_at=now()
    where tenant_id=v_tenant.id and id=v_document.id returning * into v_document;
    if v_parent.id is not null and v_document_type='invoice' then
      update accounting_core.sales_documents set status='converted',updated_by_subject_id=v_actor,updated_at=now()
      where tenant_id=v_tenant.id and id=v_parent.id;
    end if;
    insert into accounting_core.document_events(
      tenant_id,document_id,event_type,to_status,actor_subject_id,details
    ) values(v_tenant.id,v_document.id,p_action,'draft',v_actor,jsonb_build_object('totalMinor',v_document.total_minor));
    v_result:=jsonb_build_object('success',true,'action',p_action,
      'documentId',v_document.id,'documentNumber',v_document.document_number,
      'totalMinor',v_document.total_minor);

  elsif p_action in ('issue_document','cancel_document') then
    select * into v_document from accounting_core.sales_documents
    where tenant_id=v_tenant.id and id=(p_payload->>'documentId')::uuid
    for update;
    if v_document.id is null then raise exception 'document_not_found'; end if;
    v_status:=v_document.status;
    if p_action='cancel_document' then
      if v_document.status not in ('draft','sent') then raise exception 'issued_document_requires_adjustment'; end if;
      v_target_status:='cancelled';
    elsif v_document.document_type='quote' then
      v_target_status:=coalesce(nullif(p_payload->>'status',''),'sent');
      if not ((v_document.status='draft' and v_target_status in ('sent','cancelled'))
        or (v_document.status='sent' and v_target_status in ('accepted','rejected','expired','cancelled'))) then
        raise exception 'invalid_document_transition';
      end if;
    else
      if v_document.status<>'draft' then raise exception 'invalid_document_transition'; end if;
      v_target_status:='issued';
    end if;
    update accounting_core.sales_documents set
      status=v_target_status,issued_at=case when v_target_status='issued' then now() else issued_at end,
      issued_by_subject_id=case when v_target_status='issued' then v_actor else issued_by_subject_id end,
      updated_by_subject_id=v_actor,updated_at=now()
    where tenant_id=v_tenant.id and id=v_document.id returning * into v_document;
    insert into accounting_core.document_events(
      tenant_id,document_id,event_type,from_status,to_status,actor_subject_id
    ) values(v_tenant.id,v_document.id,p_action,v_status,v_target_status,v_actor);
    v_result:=jsonb_build_object('success',true,'action',p_action,
      'documentId',v_document.id,'status',v_target_status);

  elsif p_action in ('record_payment','import_handoff_payment') then
    if p_action='import_handoff_payment' then
      select handoff.contact_id,handoff.payment_amount_minor,handoff.payment_reference
        into v_id,v_amount,v_prefix
      from academy.registration_handoffs handoff
      where handoff.tenant_id=v_tenant.id
        and handoff.id=(p_payload->>'handoffId')::uuid
        and handoff.payment_status='verified'
        and handoff.payment_verified_at is not null
        and handoff.payment_amount_minor>0;
      if v_id is null then raise exception 'verified_handoff_not_found'; end if;
      select * into v_account from accounting_core.customer_accounts
      where tenant_id=v_tenant.id and contact_id=v_id;
      if v_account.id is null then
        select * into v_contact from sales_core.contacts where tenant_id=v_tenant.id and id=v_id;
        insert into accounting_core.customer_accounts(
          tenant_id,contact_id,account_number,display_name,organization_name,
          billing_email,billing_phone,payment_terms_days,created_by_subject_id,updated_by_subject_id
        ) values(
          v_tenant.id,v_contact.id,
          private_app.accounting_next_number(v_tenant.id,'customer',current_date,'CUS'),
          v_contact.full_name,v_contact.organization_name,v_contact.email,v_contact.phone,
          coalesce(v_profile.default_payment_terms_days,0),v_actor,v_actor
        ) returning * into v_account;
      end if;
      if exists(select 1 from accounting_core.payments where tenant_id=v_tenant.id
        and source_type='registration_handoff' and source_id=p_payload->>'handoffId') then
        raise exception 'payment_source_already_imported';
      end if;
      insert into accounting_core.payments(
        tenant_id,customer_account_id,payment_number,amount_minor,currency,method,
        status,external_reference,source_type,source_id,received_at,verified_at,
        verified_by_subject_id,created_by_subject_id
      ) values(
        v_tenant.id,v_account.id,
        private_app.accounting_next_number(v_tenant.id,'payment',current_date,'PAY'),
        v_amount,coalesce(v_profile.base_currency,'SAR'),'bank_transfer','verified',v_prefix,
        'registration_handoff',p_payload->>'handoffId',now(),now(),v_actor,v_actor
      ) returning * into v_payment;
    else
      select * into v_account from accounting_core.customer_accounts
      where tenant_id=v_tenant.id and id=(p_payload->>'customerAccountId')::uuid;
      if v_account.id is null then raise exception 'customer_account_not_found'; end if;
      v_amount:=(p_payload->>'amountMinor')::bigint;
      if v_amount<=0 then raise exception 'payment_amount_invalid'; end if;
      v_status:=case when coalesce((p_payload->>'verifyNow')::boolean,false)
        and private_app.has_accounting_permission(v_tenant.id,'tenant.accounting.payments.approve')
        then 'verified' else 'pending_verification' end;
      insert into accounting_core.payments(
        tenant_id,customer_account_id,payment_number,amount_minor,currency,method,
        status,external_reference,source_type,source_id,received_at,verified_at,
        verified_by_subject_id,notes,metadata,created_by_subject_id
      ) values(
        v_tenant.id,v_account.id,
        private_app.accounting_next_number(v_tenant.id,'payment',
          coalesce((p_payload->>'receivedAt')::timestamptz::date,current_date),'PAY'),
        v_amount,coalesce(nullif(upper(p_payload->>'currency'),''),v_profile.base_currency,'SAR'),
        coalesce(nullif(p_payload->>'method',''),'bank_transfer'),v_status,
        nullif(btrim(p_payload->>'externalReference'),''),
        nullif(p_payload->>'sourceType',''),nullif(p_payload->>'sourceId',''),
        coalesce((p_payload->>'receivedAt')::timestamptz,now()),
        case when v_status='verified' then now() end,
        case when v_status='verified' then v_actor end,
        nullif(btrim(p_payload->>'notes'),''),coalesce(p_payload->'metadata','{}'::jsonb),v_actor
      ) returning * into v_payment;
    end if;
    v_result:=jsonb_build_object('success',true,'action',p_action,
      'paymentId',v_payment.id,'paymentNumber',v_payment.payment_number,'status',v_payment.status);

  elsif p_action='verify_payment' then
    update accounting_core.payments set status='verified',verified_at=now(),
      verified_by_subject_id=v_actor,rejection_reason=null,updated_at=now()
    where tenant_id=v_tenant.id and id=(p_payload->>'paymentId')::uuid
      and status='pending_verification' returning * into v_payment;
    if v_payment.id is null then raise exception 'payment_not_verifiable'; end if;
    v_result:=jsonb_build_object('success',true,'action',p_action,'paymentId',v_payment.id,'status','verified');

  elsif p_action='allocate_payment' then
    select * into v_payment from accounting_core.payments
    where tenant_id=v_tenant.id and id=(p_payload->>'paymentId')::uuid and status='verified'
    for update;
    select * into v_document from accounting_core.sales_documents
    where tenant_id=v_tenant.id and id=(p_payload->>'invoiceId')::uuid
      and status='issued' and document_type in ('invoice','debit_note')
    for update;
    if v_payment.id is null or v_document.id is null then raise exception 'allocation_target_invalid'; end if;
    if v_payment.customer_account_id<>v_document.customer_account_id then raise exception 'allocation_customer_mismatch'; end if;
    v_amount:=(p_payload->>'amountMinor')::bigint;
    select coalesce(sum(amount_minor),0)::bigint into v_allocated
    from accounting_core.payment_allocations where tenant_id=v_tenant.id and payment_id=v_payment.id;
    if v_amount<=0 or v_allocated+v_amount>v_payment.amount_minor then raise exception 'payment_allocation_exceeds_available'; end if;
    select coalesce(sum(amount_minor),0)::bigint into v_allocated
    from accounting_core.payment_allocations where tenant_id=v_tenant.id and invoice_id=v_document.id;
    if v_allocated+v_amount>v_document.total_minor then raise exception 'payment_allocation_exceeds_invoice'; end if;
    insert into accounting_core.payment_allocations(
      tenant_id,payment_id,invoice_id,amount_minor,created_by_subject_id
    ) values(v_tenant.id,v_payment.id,v_document.id,v_amount,v_actor)
    on conflict(tenant_id,payment_id,invoice_id) do update
    set amount_minor=accounting_core.payment_allocations.amount_minor+excluded.amount_minor;
    v_result:=jsonb_build_object('success',true,'action',p_action,
      'paymentId',v_payment.id,'invoiceId',v_document.id,'allocatedMinor',v_amount);

  elsif p_action='issue_receipt' then
    select * into v_payment from accounting_core.payments
    where tenant_id=v_tenant.id and id=(p_payload->>'paymentId')::uuid and status in ('verified','refunded');
    if v_payment.id is null then raise exception 'payment_not_receiptable'; end if;
    insert into accounting_core.receipts(
      tenant_id,payment_id,receipt_number,issued_by_subject_id
    ) values(
      v_tenant.id,v_payment.id,
      private_app.accounting_next_number(v_tenant.id,'receipt',current_date,coalesce(v_profile.receipt_prefix,'REC')),
      v_actor
    ) on conflict(tenant_id,payment_id) do update set payment_id=excluded.payment_id
    returning * into v_receipt;
    v_result:=jsonb_build_object('success',true,'action',p_action,
      'receiptId',v_receipt.id,'receiptNumber',v_receipt.receipt_number);

  elsif p_action='create_schedule' then
    select * into v_document from accounting_core.sales_documents
    where tenant_id=v_tenant.id and id=(p_payload->>'invoiceId')::uuid
      and status='draft' and document_type in ('invoice','debit_note')
    for update;
    if v_document.id is null then raise exception 'schedule_invoice_not_editable'; end if;
    v_amount:=(p_payload->>'amountMinor')::bigint;
    select coalesce(sum(amount_minor),0)::bigint into v_allocated
    from accounting_core.payment_schedules where tenant_id=v_tenant.id and invoice_id=v_document.id;
    if v_amount<=0 or v_allocated+v_amount>v_document.total_minor then raise exception 'schedule_exceeds_invoice'; end if;
    insert into accounting_core.payment_schedules(
      tenant_id,invoice_id,installment_number,due_date,amount_minor,label,created_by_subject_id
    ) values(
      v_tenant.id,v_document.id,(p_payload->>'installmentNumber')::integer,
      (p_payload->>'dueDate')::date,v_amount,nullif(btrim(p_payload->>'label'),''),v_actor
    ) returning id into v_id;
    v_result:=jsonb_build_object('success',true,'action',p_action,'scheduleId',v_id);

  elsif p_action='record_collection_action' then
    if nullif(p_payload->>'invoiceId','') is not null and not exists(
      select 1 from accounting_core.sales_documents document
      where document.tenant_id=v_tenant.id
        and document.id=(p_payload->>'invoiceId')::uuid
        and document.customer_account_id=(p_payload->>'customerAccountId')::uuid
    ) then raise exception 'collection_invoice_customer_mismatch'; end if;
    insert into accounting_core.collection_actions(
      tenant_id,customer_account_id,invoice_id,action_type,summary,
      promised_date,promised_amount_minor,next_action_at,created_by_subject_id
    ) values(
      v_tenant.id,(p_payload->>'customerAccountId')::uuid,
      nullif(p_payload->>'invoiceId','')::uuid,coalesce(nullif(p_payload->>'type',''),'note'),
      btrim(p_payload->>'summary'),nullif(p_payload->>'promisedDate','')::date,
      (p_payload->>'promisedAmountMinor')::bigint,
      (p_payload->>'nextActionAt')::timestamptz,v_actor
    ) returning id into v_id;
    v_result:=jsonb_build_object('success',true,'action',p_action,'collectionActionId',v_id);

  elsif p_action='request_refund' then
    select * into v_payment from accounting_core.payments
    where tenant_id=v_tenant.id and id=(p_payload->>'paymentId')::uuid and status in ('verified','refunded')
    for update;
    if v_payment.id is null then raise exception 'payment_not_refundable'; end if;
    v_amount:=(p_payload->>'amountMinor')::bigint;
    select coalesce(sum(amount_minor),0)::bigint into v_refunded
    from accounting_core.refunds where tenant_id=v_tenant.id and payment_id=v_payment.id
      and status in ('requested','approved','completed');
    if v_amount<=0 or v_refunded+v_amount>v_payment.amount_minor then raise exception 'refund_exceeds_payment'; end if;
    if nullif(p_payload->>'invoiceId','') is not null and not exists(
      select 1 from accounting_core.sales_documents document
      where document.tenant_id=v_tenant.id
        and document.id=(p_payload->>'invoiceId')::uuid
        and document.customer_account_id=v_payment.customer_account_id
        and document.document_type='invoice'
    ) then raise exception 'refund_invoice_customer_mismatch'; end if;
    if nullif(p_payload->>'creditNoteId','') is not null and not exists(
      select 1 from accounting_core.sales_documents document
      where document.tenant_id=v_tenant.id
        and document.id=(p_payload->>'creditNoteId')::uuid
        and document.customer_account_id=v_payment.customer_account_id
        and document.document_type='credit_note' and document.status='issued'
    ) then raise exception 'refund_credit_note_invalid'; end if;
    insert into accounting_core.refunds(
      tenant_id,customer_account_id,payment_id,invoice_id,credit_note_id,
      amount_minor,reason,status,requested_by_subject_id
    ) values(
      v_tenant.id,v_payment.customer_account_id,v_payment.id,
      nullif(p_payload->>'invoiceId','')::uuid,nullif(p_payload->>'creditNoteId','')::uuid,
      v_amount,btrim(p_payload->>'reason'),'requested',v_actor
    ) returning * into v_refund;
    v_result:=jsonb_build_object('success',true,'action',p_action,'refundId',v_refund.id,'status',v_refund.status);

  elsif p_action in ('approve_refund','reject_refund','complete_refund') then
    select * into v_refund from accounting_core.refunds
    where tenant_id=v_tenant.id and id=(p_payload->>'refundId')::uuid for update;
    if v_refund.id is null then raise exception 'refund_not_found'; end if;
    if p_action='approve_refund' then
      if v_refund.status<>'requested' then raise exception 'refund_transition_invalid'; end if;
      v_target_status:='approved';
      update accounting_core.refunds set status='approved',approved_at=now(),approved_by_subject_id=v_actor,updated_at=now()
      where tenant_id=v_tenant.id and id=v_refund.id;
    elsif p_action='reject_refund' then
      if v_refund.status not in ('requested','approved') then raise exception 'refund_transition_invalid'; end if;
      v_target_status:='rejected';
      update accounting_core.refunds set status='rejected',approved_at=now(),approved_by_subject_id=v_actor,updated_at=now()
      where tenant_id=v_tenant.id and id=v_refund.id;
    else
      if v_refund.status<>'approved' then raise exception 'refund_transition_invalid'; end if;
      v_target_status:='completed';
      update accounting_core.refunds set status='completed',completed_at=now(),completed_by_subject_id=v_actor,
        external_reference=nullif(btrim(p_payload->>'externalReference'),''),updated_at=now()
      where tenant_id=v_tenant.id and id=v_refund.id;
      select coalesce(sum(amount_minor),0)::bigint into v_refunded
      from accounting_core.refunds where tenant_id=v_tenant.id and payment_id=v_refund.payment_id and status='completed';
      if v_refunded>=(select amount_minor from accounting_core.payments where tenant_id=v_tenant.id and id=v_refund.payment_id) then
        update accounting_core.payments set status='refunded',updated_at=now()
        where tenant_id=v_tenant.id and id=v_refund.payment_id;
      end if;
    end if;
    v_result:=jsonb_build_object('success',true,'action',p_action,'refundId',v_refund.id,'status',v_target_status);
  end if;

  perform private_app.write_audit(
    'accounting.'||p_action,'tenant_accounting',
    coalesce(v_result->>'documentId',v_result->>'paymentId',v_result->>'refundId',v_result->>'accountId'),
    v_tenant.id,jsonb_build_object('commandId',v_command_id,'result',v_result)
  );
  if v_command_id is not null then
    insert into accounting_core.commands(
      tenant_id,command_id,action,request_hash,response,actor_subject_id
    ) values(v_tenant.id,v_command_id,p_action,v_request_hash,v_result,v_actor);
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_create_opportunity(p_tenant_slug text, p_contact_id uuid, p_title text, p_stage_id uuid, p_value_minor bigint DEFAULT 0, p_course_id uuid DEFAULT NULL::uuid, p_owner_staff_id uuid DEFAULT NULL::uuid, p_expected_close_date date DEFAULT NULL::date, p_next_action_type text DEFAULT NULL::text, p_next_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_opportunity_id uuid;
  v_task_id uuid;
  v_owner_staff_id uuid;
  v_current_staff_id uuid;
  v_view_team boolean;
  v_contact sales_core.contacts%rowtype;
begin
  select t.id into v_tenant_id
  from core.tenants t
  where t.slug = p_tenant_slug
  limit 1;

  if v_tenant_id is null then raise exception 'tenant_not_found'; end if;
  if not private_app.has_tenant_permission(
    v_tenant_id,
    'tenant.crm.write'
  ) then raise exception 'forbidden'; end if;
  if p_title is null or length(trim(p_title)) < 2 then
    raise exception 'title_required';
  end if;
  if p_next_action_type is null or p_next_action_at is null then
    raise exception 'next_action_required';
  end if;
  if coalesce(p_value_minor, 0) < 0 then raise exception 'invalid_value'; end if;

  select * into v_contact
  from sales_core.contacts c
  where c.id = p_contact_id
    and c.tenant_id = v_tenant_id;
  if v_contact.id is null then raise exception 'invalid_contact'; end if;

  v_current_staff_id := private_app.current_staff_id(v_tenant_id);
  v_view_team := private_app.can_view_tenant_team(v_tenant_id);
  v_owner_staff_id := coalesce(
    p_owner_staff_id,
    v_contact.owner_staff_id,
    v_current_staff_id
  );

  if not v_view_team then
    if v_current_staff_id is null then raise exception 'staff_account_not_linked'; end if;
    if v_contact.owner_staff_id is distinct from v_current_staff_id then
      raise exception 'forbidden';
    end if;
    v_owner_staff_id := v_current_staff_id;
  end if;
  if not exists (
    select 1 from sales_core.pipeline_stages stage
    where stage.id = p_stage_id
      and stage.tenant_id = v_tenant_id
      and not stage.is_closed
  ) then raise exception 'invalid_stage'; end if;
  if v_owner_staff_id is not null and not exists (
    select 1 from people.staff_profiles sp
    where sp.id = v_owner_staff_id
      and sp.tenant_id = v_tenant_id
      and sp.employment_status = 'active'
  ) then raise exception 'invalid_owner'; end if;
  if p_course_id is not null and not exists (
    select 1 from academy.courses c
    where c.id = p_course_id
      and c.tenant_id = v_tenant_id
  ) then raise exception 'invalid_course'; end if;

  insert into sales_core.opportunities (
    tenant_id,
    contact_id,
    course_id,
    stage_id,
    owner_staff_id,
    title,
    value_minor,
    expected_close_date,
    next_action_type,
    next_action_at,
    created_by_subject_id
  )
  values (
    v_tenant_id,
    p_contact_id,
    p_course_id,
    p_stage_id,
    v_owner_staff_id,
    trim(p_title),
    coalesce(p_value_minor, 0),
    p_expected_close_date,
    p_next_action_type,
    p_next_action_at,
    private_app.current_subject_id()
  )
  returning id into v_opportunity_id;

  insert into work_core.tasks (
    tenant_id,
    title,
    description,
    assigned_staff_id,
    created_by_subject_id,
    contact_id,
    opportunity_id,
    due_at,
    metadata
  )
  values (
    v_tenant_id,
    'متابعة: ' || trim(p_title),
    'الإجراء التالي: ' || p_next_action_type,
    v_owner_staff_id,
    private_app.current_subject_id(),
    p_contact_id,
    v_opportunity_id,
    p_next_action_at,
    jsonb_build_object('source', 'opportunity_next_action')
  )
  returning id into v_task_id;

  update sales_core.contacts
  set owner_staff_id = coalesce(owner_staff_id, v_owner_staff_id),
      status = 'active'
  where id = p_contact_id;

  perform private_app.write_audit(
    'tenant.crm_opportunity_created',
    'sales_opportunity',
    v_opportunity_id::text,
    v_tenant_id,
    jsonb_build_object('title', trim(p_title), 'taskId', v_task_id)
  );

  return jsonb_build_object(
    'id', v_opportunity_id,
    'taskId', v_task_id,
    'title', trim(p_title)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_lead_intake_action_unhardened_20260806(p_tenant_slug text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant core.tenants%rowtype;
  v_current_staff_id uuid;
  v_batch sales_core.lead_import_batches%rowtype;
  v_row jsonb;
  v_import_row sales_core.lead_import_rows%rowtype;
  v_row_number integer := 0;
  v_total integer := 0;
  v_valid integer := 0;
  v_duplicate integer := 0;
  v_invalid integer := 0;
  v_distributed integer := 0;
  v_name text;
  v_phone text;
  v_whatsapp text;
  v_normalized_phone text;
  v_normalized_whatsapp text;
  v_email text;
  v_source text;
  v_campaign_name text;
  v_ad_set_name text;
  v_ad_name text;
  v_program_name text;
  v_validation_status text;
  v_validation_errors text[];
  v_duplicate_kind text;
  v_duplicate_contact_id uuid;
  v_batch_id uuid;
  v_deadline_at timestamptz;
  v_strategy text;
  v_staff_ids uuid[];
  v_row_ids uuid[];
  v_assignee_id uuid;
  v_contact_id uuid;
  v_opportunity_id uuid;
  v_task_id uuid;
  v_assignment_id uuid;
  v_stage_id uuid;
  v_course_id uuid;
  v_candidate_count integer;
  v_sales_channel text;
  v_daily_capacity integer;
  v_weight integer;
begin
  select tenant.*
  into v_tenant
  from core.tenants tenant
  where tenant.slug = p_tenant_slug
  limit 1;

  if v_tenant.id is null then
    raise exception 'tenant_not_found';
  end if;

  v_current_staff_id := private_app.current_staff_id(v_tenant.id);

  if p_action = 'import' then
    if not private_app.has_tenant_permission(
      v_tenant.id,
      'tenant.leads.import'
    ) then
      raise exception 'forbidden';
    end if;
    if jsonb_typeof(p_payload -> 'rows') <> 'array'
       or jsonb_array_length(p_payload -> 'rows') = 0 then
      raise exception 'empty_lead_import';
    end if;
    if jsonb_array_length(p_payload -> 'rows') > 5000 then
      raise exception 'lead_import_too_large';
    end if;

    v_source := coalesce(
      nullif(trim(p_payload ->> 'source'), ''),
      'sheet_import'
    );
    v_campaign_name := nullif(
      trim(p_payload ->> 'campaignName'),
      ''
    );
    v_ad_set_name := nullif(trim(p_payload ->> 'adSetName'), '');
    v_ad_name := nullif(trim(p_payload ->> 'adName'), '');

    insert into sales_core.lead_import_batches (
      tenant_id,
      batch_key,
      file_name,
      source,
      campaign_name,
      ad_set_name,
      ad_name,
      imported_by_subject_id,
      imported_by_staff_id,
      status
    )
    values (
      v_tenant.id,
      'lead-batch-' || gen_random_uuid()::text,
      coalesce(
        nullif(trim(p_payload ->> 'fileName'), ''),
        'leads.xlsx'
      ),
      v_source,
      v_campaign_name,
      v_ad_set_name,
      v_ad_name,
      private_app.current_subject_id(),
      v_current_staff_id,
      'ready'
    )
    returning * into v_batch;

    for v_row in
      select value
      from jsonb_array_elements(p_payload -> 'rows')
    loop
      v_row_number := v_row_number + 1;
      v_total := v_total + 1;
      v_name := nullif(trim(coalesce(v_row ->> 'name', '')), '');
      v_phone := nullif(trim(coalesce(v_row ->> 'phone', '')), '');
      v_whatsapp := nullif(
        trim(coalesce(v_row ->> 'whatsapp', '')),
        ''
      );
      v_normalized_phone := private_app.normalize_lead_phone(v_phone);
      v_normalized_whatsapp := private_app.normalize_lead_phone(
        v_whatsapp
      );
      v_email := nullif(
        lower(trim(coalesce(v_row ->> 'email', ''))),
        ''
      );
      v_source := coalesce(
        nullif(trim(v_row ->> 'source'), ''),
        v_batch.source
      );
      v_campaign_name := coalesce(
        nullif(trim(v_row ->> 'campaignName'), ''),
        v_batch.campaign_name
      );
      v_ad_set_name := coalesce(
        nullif(trim(v_row ->> 'adSetName'), ''),
        v_batch.ad_set_name
      );
      v_ad_name := coalesce(
        nullif(trim(v_row ->> 'adName'), ''),
        v_batch.ad_name
      );
      v_program_name := nullif(trim(v_row ->> 'program'), '');
      v_validation_status := 'valid';
      v_validation_errors := '{}'::text[];
      v_duplicate_kind := null;
      v_duplicate_contact_id := null;

      if v_name is null or length(v_name) < 2 then
        v_validation_status := 'invalid';
        v_validation_errors := array_append(
          v_validation_errors,
          'الاسم مطلوب'
        );
      end if;
      if v_normalized_phone is null
         and v_normalized_whatsapp is null then
        v_validation_status := 'invalid';
        v_validation_errors := array_append(
          v_validation_errors,
          'رقم الجوال أو واتساب غير صالح'
        );
      end if;
      if v_email is not null
         and v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
        v_validation_status := 'invalid';
        v_validation_errors := array_append(
          v_validation_errors,
          'البريد الإلكتروني غير صالح'
        );
      end if;

      if v_validation_status = 'valid'
         and exists (
           select 1
           from sales_core.lead_import_rows previous_row
           where previous_row.batch_id = v_batch.id
             and (
               (
                 v_normalized_phone is not null
                 and previous_row.normalized_phone = v_normalized_phone
               )
               or (
                 v_normalized_whatsapp is not null
                 and previous_row.normalized_whatsapp =
                   v_normalized_whatsapp
               )
               or (
                 v_email is not null
                 and lower(previous_row.email) = v_email
               )
             )
         ) then
        v_validation_status := 'duplicate';
        v_duplicate_kind := 'same_file';
        v_validation_errors := array_append(
          v_validation_errors,
          'مكرر داخل نفس الملف'
        );
      end if;

      if v_validation_status = 'valid' then
        select contact.id
        into v_duplicate_contact_id
        from sales_core.contacts contact
        where contact.tenant_id = v_tenant.id
          and (
            (
              v_normalized_phone is not null
              and (
                private_app.normalize_lead_phone(contact.phone) =
                  v_normalized_phone
                or private_app.normalize_lead_phone(contact.whatsapp) =
                  v_normalized_phone
              )
            )
            or (
              v_normalized_whatsapp is not null
              and (
                private_app.normalize_lead_phone(contact.phone) =
                  v_normalized_whatsapp
                or private_app.normalize_lead_phone(contact.whatsapp) =
                  v_normalized_whatsapp
              )
            )
            or (
              v_email is not null
              and lower(contact.email) = v_email
            )
          )
        order by contact.created_at
        limit 1;

        if v_duplicate_contact_id is not null then
          v_validation_status := 'duplicate';
          v_duplicate_kind := 'existing_contact';
          v_validation_errors := array_append(
            v_validation_errors,
            'العميل موجود مسبقًا في CRM'
          );
        end if;
      end if;

      insert into sales_core.lead_import_rows (
        tenant_id,
        batch_id,
        row_number,
        full_name,
        organization_name,
        phone,
        normalized_phone,
        whatsapp,
        normalized_whatsapp,
        email,
        source,
        campaign_name,
        ad_set_name,
        ad_name,
        program_name,
        notes,
        validation_status,
        validation_errors,
        duplicate_kind,
        duplicate_contact_id,
        queue_status,
        raw_data
      )
      values (
        v_tenant.id,
        v_batch.id,
        v_row_number,
        v_name,
        nullif(trim(v_row ->> 'organization'), ''),
        v_phone,
        v_normalized_phone,
        v_whatsapp,
        v_normalized_whatsapp,
        v_email,
        v_source,
        v_campaign_name,
        v_ad_set_name,
        v_ad_name,
        v_program_name,
        nullif(trim(v_row ->> 'notes'), ''),
        v_validation_status,
        v_validation_errors,
        v_duplicate_kind,
        v_duplicate_contact_id,
        case
          when v_validation_status = 'valid'
            then 'awaiting_distribution'
          else 'skipped'
        end,
        v_row
      );

      if v_validation_status = 'valid' then
        v_valid := v_valid + 1;
      elsif v_validation_status = 'duplicate' then
        v_duplicate := v_duplicate + 1;
      else
        v_invalid := v_invalid + 1;
      end if;
    end loop;

    update sales_core.lead_import_batches
    set total_rows = v_total,
        valid_rows = v_valid,
        duplicate_rows = v_duplicate,
        invalid_rows = v_invalid
    where id = v_batch.id;

    perform private_app.write_audit(
      'tenant.lead_batch_imported',
      'lead_import_batch',
      v_batch.id::text,
      v_tenant.id,
      jsonb_build_object(
        'fileName', v_batch.file_name,
        'totalRows', v_total,
        'validRows', v_valid,
        'duplicateRows', v_duplicate,
        'invalidRows', v_invalid,
        'source', v_batch.source,
        'campaignName', v_batch.campaign_name
      )
    );

    return jsonb_build_object(
      'batchId', v_batch.id,
      'totalRows', v_total,
      'validRows', v_valid,
      'duplicateRows', v_duplicate,
      'invalidRows', v_invalid
    );
  end if;

  if p_action = 'save_profile' then
    if not private_app.has_tenant_permission(
      v_tenant.id,
      'tenant.leads.distribute'
    ) then
      raise exception 'forbidden';
    end if;

    v_assignee_id := (p_payload ->> 'staffId')::uuid;
    v_sales_channel := coalesce(
      nullif(trim(p_payload ->> 'salesChannel'), ''),
      'online'
    );
    v_daily_capacity := coalesce(
      (p_payload ->> 'dailyCapacity')::integer,
      50
    );
    v_weight := coalesce((p_payload ->> 'weight')::integer, 1);

    if v_sales_channel not in ('online', 'field', 'hybrid') then
      raise exception 'invalid_sales_channel';
    end if;
    if v_daily_capacity not between 1 and 1000 then
      raise exception 'invalid_daily_capacity';
    end if;
    if v_weight not between 1 and 10 then
      raise exception 'invalid_distribution_weight';
    end if;
    if not exists (
      select 1
      from people.staff_profiles staff
      where staff.id = v_assignee_id
        and staff.tenant_id = v_tenant.id
        and staff.employment_status = 'active'
        and staff.role_key in (
          'sales_user',
          'sales_supervisor',
          'sales_manager'
        )
    ) then
      raise exception 'invalid_sales_assignee';
    end if;

    insert into sales_core.sales_assignment_profiles (
      tenant_id,
      staff_id,
      sales_channel,
      eligible_for_leads,
      daily_capacity,
      weight,
      updated_by_subject_id
    )
    values (
      v_tenant.id,
      v_assignee_id,
      v_sales_channel,
      coalesce((p_payload ->> 'eligible')::boolean, true),
      v_daily_capacity,
      v_weight,
      private_app.current_subject_id()
    )
    on conflict (tenant_id, staff_id) do update
    set sales_channel = excluded.sales_channel,
        eligible_for_leads = excluded.eligible_for_leads,
        daily_capacity = excluded.daily_capacity,
        weight = excluded.weight,
        updated_by_subject_id = excluded.updated_by_subject_id;

    return jsonb_build_object(
      'staffId', v_assignee_id,
      'saved', true
    );
  end if;

  if p_action = 'cancel_batch' then
    if not private_app.has_tenant_permission(
      v_tenant.id,
      'tenant.leads.import'
    ) then
      raise exception 'forbidden';
    end if;
    v_batch_id := (p_payload ->> 'batchId')::uuid;

    select batch.*
    into v_batch
    from sales_core.lead_import_batches batch
    where batch.id = v_batch_id
      and batch.tenant_id = v_tenant.id
    for update;

    if v_batch.id is null then
      raise exception 'lead_batch_not_found';
    end if;
    if v_batch.distributed_rows > 0 then
      raise exception 'lead_batch_already_distributed';
    end if;

    update sales_core.lead_import_rows
    set queue_status = 'cancelled'
    where batch_id = v_batch.id
      and validation_status = 'valid'
      and queue_status = 'awaiting_distribution';

    update sales_core.lead_import_batches
    set status = 'cancelled'
    where id = v_batch.id;

    return jsonb_build_object('batchId', v_batch.id, 'cancelled', true);
  end if;

  if p_action = 'distribute' then
    if not private_app.has_tenant_permission(
      v_tenant.id,
      'tenant.leads.distribute'
    ) then
      raise exception 'forbidden';
    end if;

    v_batch_id := (p_payload ->> 'batchId')::uuid;
    v_strategy := coalesce(
      nullif(trim(p_payload ->> 'strategy'), ''),
      'fair'
    );
    v_deadline_at := (p_payload ->> 'deadlineAt')::timestamptz;

    if v_strategy not in ('fair', 'online_only', 'selected') then
      raise exception 'invalid_distribution_strategy';
    end if;
    if v_deadline_at is null or v_deadline_at <= now() then
      raise exception 'invalid_distribution_deadline';
    end if;
    if v_deadline_at > now() + interval '90 days' then
      raise exception 'distribution_deadline_too_far';
    end if;

    select coalesce(array_agg(value::uuid), '{}'::uuid[])
    into v_staff_ids
    from jsonb_array_elements_text(
      coalesce(p_payload -> 'staffIds', '[]'::jsonb)
    );

    select coalesce(array_agg(value::uuid), '{}'::uuid[])
    into v_row_ids
    from jsonb_array_elements_text(
      coalesce(p_payload -> 'rowIds', '[]'::jsonb)
    );

    if v_strategy = 'selected'
       and cardinality(v_staff_ids) = 0 then
      raise exception 'distribution_staff_required';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_tenant.id::text, 1729)
    );

    select batch.*
    into v_batch
    from sales_core.lead_import_batches batch
    where batch.id = v_batch_id
      and batch.tenant_id = v_tenant.id
      and batch.status in ('ready', 'partially_distributed')
    for update;

    if v_batch.id is null then
      raise exception 'lead_batch_not_ready';
    end if;

    select count(*)
    into v_candidate_count
    from people.staff_profiles staff
    left join sales_core.sales_assignment_profiles profile
      on profile.staff_id = staff.id
     and profile.tenant_id = staff.tenant_id
    where staff.tenant_id = v_tenant.id
      and staff.employment_status = 'active'
      and staff.role_key in (
        'sales_user',
        'sales_supervisor',
        'sales_manager'
      )
      and (
        (
          v_strategy = 'selected'
          and staff.id = any(v_staff_ids)
        )
        or (
          v_strategy = 'fair'
          and coalesce(profile.eligible_for_leads, false)
        )
        or (
          v_strategy = 'online_only'
          and coalesce(profile.eligible_for_leads, false)
          and coalesce(profile.sales_channel, 'online') in (
            'online',
            'hybrid'
          )
        )
      );

    if v_candidate_count = 0 then
      if v_strategy = 'online_only' then
        raise exception 'no_online_sales_team';
      end if;
      raise exception 'no_sales_team';
    end if;

    select stage.id
    into v_stage_id
    from sales_core.pipeline_stages stage
    where stage.tenant_id = v_tenant.id
      and stage.stage_key = 'new_lead'
    limit 1;

    if v_stage_id is null then
      raise exception 'invalid_stage';
    end if;

    for v_import_row in
      select row_data.*
      from sales_core.lead_import_rows row_data
      where row_data.batch_id = v_batch.id
        and row_data.tenant_id = v_tenant.id
        and row_data.validation_status = 'valid'
        and row_data.queue_status = 'awaiting_distribution'
        and (
          cardinality(v_row_ids) = 0
          or row_data.id = any(v_row_ids)
        )
      order by row_data.row_number
      for update skip locked
    loop
      select staff.id
      into v_assignee_id
      from people.staff_profiles staff
      left join sales_core.sales_assignment_profiles profile
        on profile.staff_id = staff.id
       and profile.tenant_id = staff.tenant_id
      where staff.tenant_id = v_tenant.id
        and staff.employment_status = 'active'
        and staff.role_key in (
          'sales_user',
          'sales_supervisor',
          'sales_manager'
        )
        and (
          (
            v_strategy = 'selected'
            and staff.id = any(v_staff_ids)
          )
          or (
            v_strategy = 'fair'
            and coalesce(profile.eligible_for_leads, false)
          )
          or (
            v_strategy = 'online_only'
            and coalesce(profile.eligible_for_leads, false)
            and coalesce(profile.sales_channel, 'online') in (
              'online',
              'hybrid'
            )
          )
        )
        and (
          select count(*)
          from sales_core.lead_assignments today_assignment
          where today_assignment.assigned_staff_id = staff.id
            and (
              today_assignment.assigned_at
              at time zone v_tenant.timezone
            )::date = (
              now() at time zone v_tenant.timezone
            )::date
        ) < coalesce(profile.daily_capacity, 50)
      order by
        (
          (
            select count(*)
            from sales_core.lead_assignments active_assignment
            where active_assignment.assigned_staff_id = staff.id
              and active_assignment.status = 'active'
              and active_assignment.first_action_at is null
          )::numeric
          / greatest(coalesce(profile.weight, 1), 1)
        ),
        profile.last_assigned_at nulls first,
        staff.id
      limit 1;

      if v_assignee_id is null then
        exit;
      end if;

      v_course_id := null;
      if v_import_row.program_name is not null then
        select course.id
        into v_course_id
        from academy.courses course
        where course.tenant_id = v_tenant.id
          and course.status = 'active'
          and (
            lower(course.course_code) =
              lower(v_import_row.program_name)
            or lower(course.title_ar) =
              lower(v_import_row.program_name)
            or lower(coalesce(course.title_en, '')) =
              lower(v_import_row.program_name)
          )
        order by course.created_at
        limit 1;
      end if;

      insert into sales_core.contacts (
        tenant_id,
        contact_key,
        full_name,
        organization_name,
        phone,
        whatsapp,
        email,
        source,
        status,
        owner_staff_id,
        interest_course_id,
        notes,
        created_by_subject_id,
        metadata,
        lead_status,
        lead_quality,
        next_action_type,
        next_action_at,
        campaign_name,
        ad_name
      )
      values (
        v_tenant.id,
        'lead-import-' || v_import_row.id::text,
        v_import_row.full_name,
        v_import_row.organization_name,
        v_import_row.phone,
        v_import_row.whatsapp,
        v_import_row.email,
        v_import_row.source,
        'new',
        v_assignee_id,
        v_course_id,
        v_import_row.notes,
        private_app.current_subject_id(),
        jsonb_strip_nulls(jsonb_build_object(
          'model', 'lead_intake_v2',
          'importBatchId', v_batch.id,
          'importRowId', v_import_row.id,
          'normalizedPhone', v_import_row.normalized_phone,
          'normalizedWhatsapp', v_import_row.normalized_whatsapp,
          'programName', v_import_row.program_name,
          'adSetName', v_import_row.ad_set_name
        )),
        'new',
        'unrated',
        'call',
        v_deadline_at,
        v_import_row.campaign_name,
        v_import_row.ad_name
      )
      returning id into v_contact_id;

      insert into sales_core.opportunities (
        tenant_id,
        opportunity_key,
        contact_id,
        course_id,
        stage_id,
        owner_staff_id,
        title,
        value_minor,
        next_action_type,
        next_action_at,
        status,
        created_by_subject_id,
        metadata
      )
      values (
        v_tenant.id,
        'lead-import-' || v_import_row.id::text,
        v_contact_id,
        v_course_id,
        v_stage_id,
        v_assignee_id,
        case
          when v_import_row.program_name is null
            then 'متابعة ' || v_import_row.full_name
          else
            'متابعة ' || v_import_row.full_name
            || ' — ' || v_import_row.program_name
        end,
        0,
        'call',
        v_deadline_at,
        'open',
        private_app.current_subject_id(),
        jsonb_build_object(
          'model', 'lead_intake_v2',
          'importBatchId', v_batch.id,
          'importRowId', v_import_row.id
        )
      )
      returning id into v_opportunity_id;

      insert into sales_core.lead_assignments (
        tenant_id,
        batch_id,
        import_row_id,
        contact_id,
        opportunity_id,
        assigned_staff_id,
        assigned_by_staff_id,
        assigned_by_subject_id,
        assignment_strategy,
        deadline_at,
        metadata
      )
      values (
        v_tenant.id,
        v_batch.id,
        v_import_row.id,
        v_contact_id,
        v_opportunity_id,
        v_assignee_id,
        v_current_staff_id,
        private_app.current_subject_id(),
        v_strategy,
        v_deadline_at,
        jsonb_build_object(
          'source', 'lead_queue',
          'campaignName', v_import_row.campaign_name,
          'adSetName', v_import_row.ad_set_name,
          'adName', v_import_row.ad_name
        )
      )
      returning id into v_assignment_id;

      insert into work_core.tasks (
        tenant_id,
        task_key,
        title,
        description,
        priority,
        status,
        assigned_staff_id,
        created_by_subject_id,
        contact_id,
        opportunity_id,
        starts_at,
        due_at,
        metadata
      )
      values (
        v_tenant.id,
        'lead-assignment-' || v_assignment_id::text,
        'متابعة العميل: ' || v_import_row.full_name,
        concat_ws(
          ' — ',
          nullif(v_import_row.program_name, ''),
          case
            when v_import_row.campaign_name is not null
              then 'الحملة: ' || v_import_row.campaign_name
          end,
          case
            when v_import_row.ad_name is not null
              then 'الإعلان: ' || v_import_row.ad_name
          end
        ),
        'high',
        'todo',
        v_assignee_id,
        private_app.current_subject_id(),
        v_contact_id,
        v_opportunity_id,
        now(),
        v_deadline_at,
        jsonb_build_object(
          'source', 'lead_assignment',
          'assignmentId', v_assignment_id,
          'batchId', v_batch.id,
          'rowId', v_import_row.id,
          'deadlineType', 'first_action'
        )
      )
      returning id into v_task_id;

      update sales_core.lead_assignments
      set task_id = v_task_id
      where id = v_assignment_id;

      update sales_core.lead_import_rows
      set queue_status = 'assigned',
          contact_id = v_contact_id
      where id = v_import_row.id;

      insert into sales_core.sales_assignment_profiles (
        tenant_id,
        staff_id,
        sales_channel,
        eligible_for_leads,
        daily_capacity,
        last_assigned_at,
        updated_by_subject_id
      )
      values (
        v_tenant.id,
        v_assignee_id,
        'online',
        true,
        50,
        now(),
        private_app.current_subject_id()
      )
      on conflict (tenant_id, staff_id) do update
      set last_assigned_at = excluded.last_assigned_at;

      v_distributed := v_distributed + 1;
    end loop;

    update sales_core.lead_import_batches batch
    set distributed_rows = (
          select count(*)
          from sales_core.lead_import_rows row_data
          where row_data.batch_id = batch.id
            and row_data.queue_status = 'assigned'
        ),
        last_distributed_by_staff_id = v_current_staff_id,
        last_distribution_strategy = v_strategy,
        last_deadline_at = v_deadline_at,
        distributed_at = case
          when v_distributed > 0 then now()
          else batch.distributed_at
        end,
        status = case
          when exists (
            select 1
            from sales_core.lead_import_rows remaining_row
            where remaining_row.batch_id = batch.id
              and remaining_row.validation_status = 'valid'
              and remaining_row.queue_status =
                'awaiting_distribution'
          ) then 'partially_distributed'
          else 'distributed'
        end
    where batch.id = v_batch.id;

    perform private_app.write_audit(
      'tenant.leads_distributed',
      'lead_import_batch',
      v_batch.id::text,
      v_tenant.id,
      jsonb_build_object(
        'distributed', v_distributed,
        'strategy', v_strategy,
        'deadlineAt', v_deadline_at,
        'candidateCount', v_candidate_count
      )
    );

    return jsonb_build_object(
      'batchId', v_batch.id,
      'distributed', v_distributed,
      'strategy', v_strategy,
      'deadlineAt', v_deadline_at,
      'teamSize', v_candidate_count
    );
  end if;

  raise exception 'invalid_lead_intake_action';
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_move_opportunity(p_tenant_slug text, p_opportunity_id uuid, p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_opportunity sales_core.opportunities%rowtype;
  v_stage sales_core.pipeline_stages%rowtype;
  v_current_staff_id uuid;
  v_view_team boolean;
  v_status text;
begin
  select t.id into v_tenant_id
  from core.tenants t
  where t.slug = p_tenant_slug
  limit 1;
  if v_tenant_id is null then raise exception 'tenant_not_found'; end if;
  if not private_app.has_tenant_permission(
    v_tenant_id,
    'tenant.crm.write'
  ) then raise exception 'forbidden'; end if;

  select * into v_opportunity
  from sales_core.opportunities o
  where o.id = p_opportunity_id
    and o.tenant_id = v_tenant_id
  for update;
  if v_opportunity.id is null then raise exception 'opportunity_not_found'; end if;

  v_current_staff_id := private_app.current_staff_id(v_tenant_id);
  v_view_team := private_app.can_view_tenant_team(v_tenant_id);
  if not v_view_team
     and v_opportunity.owner_staff_id is distinct from v_current_staff_id then
    raise exception 'forbidden';
  end if;

  select * into v_stage
  from sales_core.pipeline_stages stage
  where stage.id = p_stage_id
    and stage.tenant_id = v_tenant_id;
  if v_stage.id is null then raise exception 'invalid_stage'; end if;

  v_status := case
    when not v_stage.is_closed then 'open'
    when v_stage.is_won then 'won'
    else 'lost'
  end;

  update sales_core.opportunities
  set stage_id = p_stage_id,
      status = v_status,
      next_action_type = case when v_stage.is_closed then null else next_action_type end,
      next_action_at = case when v_stage.is_closed then null else next_action_at end
  where id = p_opportunity_id;

  if v_stage.is_closed then
    update work_core.tasks
    set status = 'cancelled'
    where opportunity_id = p_opportunity_id
      and status in ('todo', 'in_progress');
  end if;

  perform private_app.write_audit(
    'tenant.crm_opportunity_moved',
    'sales_opportunity',
    p_opportunity_id::text,
    v_tenant_id,
    jsonb_build_object('stageKey', v_stage.stage_key, 'status', v_status)
  );

  return jsonb_build_object(
    'id', p_opportunity_id,
    'stageId', p_stage_id,
    'status', v_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_record_sales_followup_v5(p_tenant_slug text, p_contact_id uuid, p_activity_type text, p_summary text, p_lead_status text, p_lead_quality text DEFAULT 'unrated'::text, p_next_action_type text DEFAULT NULL::text, p_next_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_course_id uuid DEFAULT NULL::uuid, p_course_run_id uuid DEFAULT NULL::uuid, p_payment_amount_minor bigint DEFAULT NULL::bigint, p_payment_reference text DEFAULT NULL::text, p_preferred_start_date date DEFAULT NULL::date, p_closure_reason text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text, p_task_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_selected_task work_core.tasks%rowtype;
  v_result jsonb;
  v_result_task_id uuid;
  v_lead_status text := p_lead_status;
  v_lead_quality text := coalesce(p_lead_quality, 'unrated');
  v_closure_reason text := p_closure_reason;
  v_normalized boolean := false;
begin
  select tenant.id
  into v_tenant_id
  from core.tenants tenant
  where tenant.slug = p_tenant_slug
  limit 1;

  if v_tenant_id is null then raise exception 'tenant_not_found'; end if;
  if not private_app.has_tenant_permission(
    v_tenant_id,
    'tenant.crm.write'
  ) then raise exception 'forbidden'; end if;

  if v_lead_quality = 'unqualified'
     and v_lead_status in (
       'new', 'no_answer', 'busy', 'phone_off', 'follow_up',
       'interested', 'very_interested', 'awaiting_payment', 'postponed'
     )
  then
    v_lead_status := 'unqualified';
    v_closure_reason := coalesce(
      nullif(trim(v_closure_reason), ''),
      'جودة العميل غير مؤهل'
    );
    v_normalized := true;
  elsif v_lead_status = 'unqualified'
        and v_lead_quality <> 'unqualified'
  then
    v_lead_quality := 'unqualified';
    v_normalized := true;
  elsif v_lead_quality = 'unqualified'
        and v_lead_status in ('payment_submitted', 'paid')
  then
    raise exception 'unqualified_quality_requires_closed_status';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_tenant_id::text || ':' || p_contact_id::text,
      31603
    )
  );

  perform contact.id
  from sales_core.contacts contact
  where contact.id = p_contact_id
    and contact.tenant_id = v_tenant_id
  for update;

  if not found then raise exception 'invalid_contact'; end if;

  if p_task_id is not null then
    select task.*
    into v_selected_task
    from work_core.tasks task
    where task.id = p_task_id
      and task.tenant_id = v_tenant_id
      and task.contact_id = p_contact_id
      and task.status in ('todo', 'in_progress')
      and coalesce(task.metadata ->> 'source', '') in (
        'lead_assignment',
        'opportunity_next_action',
        'activity_next_action',
        'lead_next_action',
        'sales_followup'
      )
    for update;

    if v_selected_task.id is null then
      raise exception 'task_not_followup';
    end if;
  end if;

  v_result := public.v2_tenant_record_sales_followup_v4(
    p_tenant_slug => p_tenant_slug,
    p_contact_id => p_contact_id,
    p_activity_type => p_activity_type,
    p_summary => p_summary,
    p_lead_status => v_lead_status,
    p_lead_quality => v_lead_quality,
    p_next_action_type => case
      when v_lead_status in (
        'new', 'no_answer', 'busy', 'phone_off', 'follow_up',
        'interested', 'very_interested', 'awaiting_payment', 'postponed'
      ) then p_next_action_type
      else null
    end,
    p_next_action_at => case
      when v_lead_status in (
        'new', 'no_answer', 'busy', 'phone_off', 'follow_up',
        'interested', 'very_interested', 'awaiting_payment', 'postponed'
      ) then p_next_action_at
      else null
    end,
    p_course_id => p_course_id,
    p_course_run_id => p_course_run_id,
    p_payment_amount_minor => p_payment_amount_minor,
    p_payment_reference => p_payment_reference,
    p_preferred_start_date => p_preferred_start_date,
    p_closure_reason => v_closure_reason,
    p_contact_name => p_contact_name
  );

  if p_task_id is not null then
    v_result_task_id := nullif(coalesce(
      v_result ->> 'followupTaskId',
      v_result ->> 'taskId'
    ), '')::uuid;
    if v_result_task_id is distinct from p_task_id then
      raise exception 'task_transition_conflict';
    end if;
  end if;

  return v_result || jsonb_strip_nulls(jsonb_build_object(
    'selectedTaskId', p_task_id,
    'taskUpdateMode', 'bound_task_id_v5',
    'lifecycleNormalized', v_normalized,
    'normalizedLeadStatus', case when v_normalized then v_lead_status end,
    'normalizedLeadQuality', case when v_normalized then v_lead_quality end
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_record_sales_followup_v6(p_tenant_slug text, p_contact_id uuid, p_activity_type text, p_summary text, p_lead_status text, p_course_interests jsonb, p_additional_phones jsonb, p_expected_revision text, p_command_id uuid, p_lead_quality text DEFAULT 'unrated'::text, p_next_action_type text DEFAULT NULL::text, p_next_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_payment_course_id uuid DEFAULT NULL::uuid, p_payment_amount_minor bigint DEFAULT NULL::bigint, p_payment_reference text DEFAULT NULL::text, p_closure_reason text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text, p_task_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_contact sales_core.contacts%rowtype; v_context jsonb; v_previous jsonb; v_result jsonb;
  v_request_hash text; v_command sales_core.followup_commands%rowtype;
  v_item jsonb; v_course_id uuid; v_run_id uuid; v_session_id uuid; v_position integer := 0;
  v_courses uuid[] := '{}'::uuid[]; v_phones text[] := '{}'::text[]; v_phone text;
  v_selected jsonb; v_primary_course uuid; v_attendance_at timestamptz; v_start_date date;
begin
  v_contact := private_app.sales_followup_contact(p_tenant_slug,p_contact_id,true);
  if p_command_id is null or p_expected_revision is null then raise exception 'followup_reload_required'; end if;
  if jsonb_typeof(p_course_interests) is distinct from 'array' or jsonb_array_length(p_course_interests)>20
     or jsonb_typeof(p_additional_phones) is distinct from 'array' or jsonb_array_length(p_additional_phones)>10
    then raise exception 'invalid_followup_details'; end if;
  v_request_hash := md5(jsonb_build_array(p_contact_id,p_activity_type,p_summary,p_lead_status,p_course_interests,
    p_additional_phones,p_expected_revision,p_lead_quality,p_next_action_type,p_next_action_at,p_payment_course_id,
    p_payment_amount_minor,p_payment_reference,p_closure_reason,p_contact_name,p_task_id)::text);
  -- Match the existing identity editor lock order, then the existing task lifecycle lock.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_contact.tenant_id::text,1729));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_contact.tenant_id::text || ':' || p_contact_id::text,31603));
  perform id from sales_core.contacts where tenant_id=v_contact.tenant_id and id=p_contact_id for update;
  v_contact := private_app.sales_followup_contact(p_tenant_slug,p_contact_id,true);
  select * into v_command from sales_core.followup_commands where tenant_id=v_contact.tenant_id and command_id=p_command_id;
  if found then
    if v_command.contact_id<>p_contact_id or v_command.actor_id<>private_app.current_subject_id()
       or v_command.request_hash<>v_request_hash then raise exception 'followup_command_conflict'; end if;
    return v_command.result || jsonb_build_object('replayed',true);
  end if;
  v_context := public.v1_tenant_sales_followup_context(p_tenant_slug,p_contact_id);
  if v_context->>'revision' is distinct from p_expected_revision then raise exception 'followup_changed_reload'; end if;
    v_previous := v_context - 'revision' - 'timezone';

  for v_item in select value from jsonb_array_elements(p_course_interests) loop
    if jsonb_typeof(v_item)<>'object' then raise exception 'invalid_followup_details'; end if;
    v_course_id := nullif(v_item->>'courseId','')::uuid;
    v_run_id := nullif(v_item->>'courseRunId','')::uuid;
    v_session_id := nullif(v_item->>'attendanceSessionId','')::uuid;
    if v_course_id is null or v_course_id=any(v_courses) then raise exception 'duplicate_or_missing_course'; end if;
    if not exists(select 1 from academy.courses where tenant_id=v_contact.tenant_id and id=v_course_id and status<>'archived')
      then raise exception 'invalid_course'; end if;
    if v_run_id is not null and not exists(select 1 from academy.course_runs
      where tenant_id=v_contact.tenant_id and course_id=v_course_id and id=v_run_id and status in ('planning','open','in_progress'))
      then raise exception 'invalid_course_run'; end if;
    if v_session_id is not null and (v_run_id is null or not exists(select 1 from academy.course_run_sessions
      where tenant_id=v_contact.tenant_id and course_run_id=v_run_id and id=v_session_id and status='scheduled'))
      then raise exception 'invalid_attendance_session'; end if;
    v_courses := array_append(v_courses,v_course_id);
  end loop;
  v_primary_course := v_courses[1];
  if p_lead_status='payment_submitted' then
    if p_payment_course_id is null or not (p_payment_course_id=any(v_courses)) then raise exception 'payment_course_required'; end if;
    select item into v_selected from jsonb_array_elements(p_course_interests) item where item->>'courseId'=p_payment_course_id::text;
    v_run_id := nullif(v_selected->>'courseRunId','')::uuid;
    v_session_id := nullif(v_selected->>'attendanceSessionId','')::uuid;
    select coalesce(s.starts_at,r.starts_at) into v_attendance_at from academy.course_runs r
      left join academy.course_run_sessions s on s.tenant_id=r.tenant_id and s.course_run_id=r.id and s.id=v_session_id
      where r.tenant_id=v_contact.tenant_id and r.id=v_run_id;
    v_start_date := (v_attendance_at at time zone coalesce(nullif(v_context->>'timezone',''),'UTC'))::date;
  else v_run_id := null; v_session_id := null; end if;

  for v_item in select value from jsonb_array_elements(p_additional_phones) loop
    if jsonb_typeof(v_item)<>'string' or length(v_item #>> '{}')>40 then raise exception 'invalid_phone'; end if;
    v_phone := private_app.normalize_lead_phone(v_item #>> '{}');
    if v_phone is null then raise exception 'invalid_phone'; end if;
    if v_phone=any(v_phones) or v_phone in (private_app.normalize_lead_phone(v_contact.phone),private_app.normalize_lead_phone(v_contact.whatsapp))
      then raise exception 'duplicate_additional_phone'; end if;
    if exists(select 1 from sales_core.contact_identities where tenant_id=v_contact.tenant_id and identity_type='phone'
      and identity_value=v_phone and contact_id<>p_contact_id) then raise exception 'duplicate_contact_identity'; end if;
    v_phones := array_append(v_phones,v_phone);
  end loop;

  -- Explicit clear is supported; the legacy scalar remains the first interest for old readers.
  update sales_core.contacts set interest_course_id=v_primary_course where tenant_id=v_contact.tenant_id and id=p_contact_id;
  v_result := public.v2_tenant_record_sales_followup_v5(
    p_tenant_slug=>p_tenant_slug,p_contact_id=>p_contact_id,p_activity_type=>p_activity_type,p_summary=>p_summary,
    p_lead_status=>p_lead_status,p_lead_quality=>p_lead_quality,p_next_action_type=>p_next_action_type,p_next_action_at=>p_next_action_at,
    p_course_id=>case when p_lead_status='payment_submitted' then p_payment_course_id else v_primary_course end,
    p_course_run_id=>v_run_id,p_payment_amount_minor=>p_payment_amount_minor,p_payment_reference=>p_payment_reference,
    p_preferred_start_date=>v_start_date,p_closure_reason=>p_closure_reason,p_contact_name=>p_contact_name,p_task_id=>p_task_id
  );
  update sales_core.contacts set interest_course_id=v_primary_course where tenant_id=v_contact.tenant_id and id=p_contact_id;
  delete from sales_core.contact_course_interests where tenant_id=v_contact.tenant_id and contact_id=p_contact_id and not(course_id=any(v_courses));
  for v_item in select value from jsonb_array_elements(p_course_interests) loop
    insert into sales_core.contact_course_interests(tenant_id,contact_id,course_id,course_run_id,attendance_session_id,position)
    values(v_contact.tenant_id,p_contact_id,(v_item->>'courseId')::uuid,nullif(v_item->>'courseRunId','')::uuid,
      nullif(v_item->>'attendanceSessionId','')::uuid,v_position)
    on conflict(tenant_id,contact_id,course_id) do update set course_run_id=excluded.course_run_id,
      attendance_session_id=excluded.attendance_session_id,position=excluded.position,updated_at=now();
    v_position := v_position+1;
  end loop;
  update sales_core.contact_identities set source_slot='historical_alias',updated_at=now()
    where tenant_id=v_contact.tenant_id and contact_id=p_contact_id and source_slot='additional_phone' and not(identity_value=any(v_phones));
  foreach v_phone in array v_phones loop
    insert into sales_core.contact_identities(tenant_id,contact_id,identity_type,identity_value,source_slot,is_alias)
    values(v_contact.tenant_id,p_contact_id,'phone',v_phone,'additional_phone',true)
    on conflict(tenant_id,identity_type,identity_value) do update set source_slot='additional_phone',is_alias=true,updated_at=now()
      where sales_core.contact_identities.contact_id=excluded.contact_id;
    if not found then raise exception 'duplicate_contact_identity'; end if;
  end loop;
  v_context := public.v1_tenant_sales_followup_context(p_tenant_slug,p_contact_id);
  update sales_core.activities set metadata=metadata || jsonb_build_object('courseInterests',v_context->'courseInterests',
    'additionalPhones',v_context->'additionalPhones','followupCommandId',p_command_id)
    where tenant_id=v_contact.tenant_id and id=(v_result->>'id')::uuid;
  if v_result->>'handoffId' is not null then
    update academy.registration_handoffs set metadata=metadata || jsonb_build_object(
      'attendanceSessionId',v_session_id,'attendanceAt',v_attendance_at,'courseInterests',v_context->'courseInterests')
      where tenant_id=v_contact.tenant_id and contact_id=p_contact_id and id=(v_result->>'handoffId')::uuid;
  end if;
  perform private_app.write_audit('tenant.sales_followup_details_updated','sales_contact',p_contact_id::text,v_contact.tenant_id,
    jsonb_build_object('old',v_previous,'new',v_context-'revision'-'timezone','commandId',p_command_id));
  v_result := v_result || jsonb_build_object('followupDetails',v_context);
  insert into sales_core.followup_commands(tenant_id,command_id,contact_id,actor_id,request_hash,result)
    values(v_contact.tenant_id,p_command_id,p_contact_id,private_app.current_subject_id(),v_request_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.v2_tenant_update_admission(p_tenant_slug text, p_handoff_id uuid, p_action text, p_course_id uuid DEFAULT NULL::uuid, p_course_run_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid; contact uuid;
begin
 select id into t from core.tenants where slug=p_tenant_slug;
 if private_app.current_subject_id() is null or t is null or not (private_app.has_tenant_permission(t,'tenant.admissions.write') or (p_action='verify_payment' and private_app.training_journey_payment_authorized_v1(t) and exists(select 1 from academy.training_financial_links where tenant_id=t and handoff_id=p_handoff_id)) or (p_action='complete' and p_course_id is null and p_course_run_id is null and private_app.training_journey_auto_admission_authorized_v1(t,p_handoff_id)))
  then raise exception 'forbidden';end if;
 select contact_id into contact from academy.registration_handoffs where tenant_id=t and id=p_handoff_id;
 if contact is null then raise exception 'admission_not_found';end if;
 perform 1 from commerce_sync.connections where tenant_id=t and id in (
  select w.connection_id from sales_core.commerce_admission_lines l join sales_core.commerce_order_work_items w
   on w.tenant_id=t and w.id=l.work_item_id where l.tenant_id=t and l.handoff_id=p_handoff_id) order by id for update;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':'||contact::text,31603));
 perform 1 from sales_core.contacts where tenant_id=t and id=contact for update;
 return private_app.update_admission_before_commerce_v1(p_tenant_slug,p_handoff_id,p_action,p_course_id,p_course_run_id,p_notes,p_reason);
end $function$

CREATE OR REPLACE FUNCTION public.v2_tenant_update_task_status(p_tenant_slug text, p_task_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_task work_core.tasks%rowtype;
  v_current_staff_id uuid;
  v_view_team boolean;
  v_completed_at timestamptz;
  v_completion_timing text;
begin
  select t.id into v_tenant_id
  from core.tenants t
  where t.slug = p_tenant_slug
  limit 1;
  if v_tenant_id is null then raise exception 'tenant_not_found'; end if;
  if not private_app.has_tenant_permission(
    v_tenant_id,
    'tenant.work.write'
  ) then raise exception 'forbidden'; end if;
  if p_status not in ('todo', 'in_progress', 'completed', 'cancelled') then
    raise exception 'invalid_task_status';
  end if;

  select * into v_task
  from work_core.tasks task
  where task.id = p_task_id
    and task.tenant_id = v_tenant_id
  for update;
  if v_task.id is null then raise exception 'task_not_found'; end if;

  v_current_staff_id := private_app.current_staff_id(v_tenant_id);
  v_view_team := private_app.can_view_tenant_team(v_tenant_id);
  if not v_view_team
     and v_task.assigned_staff_id is distinct from v_current_staff_id then
    raise exception 'forbidden';
  end if;

  if p_status = 'completed' then
    v_completed_at := now();
    v_completion_timing := case
      when now() <= v_task.due_at then 'on_time'
      else 'late'
    end;
  else
    v_completed_at := null;
    v_completion_timing := null;
  end if;

  update work_core.tasks
  set status = p_status,
      completed_at = v_completed_at,
      completion_timing = v_completion_timing
  where id = p_task_id;

  perform private_app.write_audit(
    'tenant.work_task_status_updated',
    'work_task',
    p_task_id::text,
    v_tenant_id,
    jsonb_build_object(
      'status', p_status,
      'completionTiming', v_completion_timing
    )
  );

  return jsonb_build_object(
    'id', p_task_id,
    'status', p_status,
    'completionTiming', v_completion_timing
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.v3_tenant_transition_task(p_tenant_slug text, p_task_id uuid, p_status text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_task work_core.tasks%rowtype;
  v_current_staff_id uuid;
  v_view_team boolean;
  v_next_status text;
  v_next_due_at timestamptz;
  v_completed_at timestamptz;
  v_completion_timing text;
  v_clean_note text;
begin
  select tenant.id
  into v_tenant_id
  from core.tenants tenant
  where tenant.slug = p_tenant_slug
  limit 1;

  if v_tenant_id is null then raise exception 'tenant_not_found'; end if;
  if not private_app.has_tenant_permission(
    v_tenant_id,
    'tenant.work.write'
  ) then raise exception 'forbidden'; end if;
  if p_status is not null
     and p_status not in ('todo', 'in_progress', 'completed', 'cancelled') then
    raise exception 'invalid_task_status';
  end if;

  select task.*
  into v_task
  from work_core.tasks task
  where task.id = p_task_id
    and task.tenant_id = v_tenant_id
  for update;

  if v_task.id is null then raise exception 'task_not_found'; end if;

  v_current_staff_id := private_app.current_staff_id(v_tenant_id);
  v_view_team := private_app.can_view_tenant_team(v_tenant_id);
  if not v_view_team
     and v_task.assigned_staff_id is distinct from v_current_staff_id then
    raise exception 'forbidden';
  end if;

  v_next_status := coalesce(p_status, v_task.status);
  v_next_due_at := coalesce(p_due_at, v_task.due_at);
  v_clean_note := nullif(btrim(coalesce(p_note, '')), '');

  if length(coalesce(v_clean_note, '')) > 2000 then
    raise exception 'task_note_too_long';
  end if;
  if v_task.status in ('completed', 'cancelled')
     and v_next_status = v_task.status
     and v_next_due_at is distinct from v_task.due_at then
    raise exception 'task_closed';
  end if;
  if v_next_status = v_task.status
     and v_next_due_at is not distinct from v_task.due_at
     and v_clean_note is null then
    raise exception 'task_transition_required';
  end if;

  if v_next_status = 'completed' then
    v_completed_at := case
      when v_task.status = 'completed' then v_task.completed_at
      else now()
    end;
    v_completion_timing := case
      when v_completed_at <= v_next_due_at then 'on_time'
      else 'late'
    end;
  else
    v_completed_at := null;
    v_completion_timing := null;
  end if;

  update work_core.tasks
  set status = v_next_status,
      due_at = v_next_due_at,
      completed_at = v_completed_at,
      completion_timing = v_completion_timing,
      metadata = metadata || jsonb_build_object(
        'lastTransition',
        jsonb_strip_nulls(jsonb_build_object(
          'fromStatus', v_task.status,
          'toStatus', v_next_status,
          'fromDueAt', v_task.due_at,
          'toDueAt', v_next_due_at,
          'note', v_clean_note,
          'actorSubjectId', private_app.current_subject_id(),
          'at', now(),
          'mode', 'same_task_row_v3'
        ))
      ),
      updated_at = now()
  where id = v_task.id
    and tenant_id = v_tenant_id;

  perform private_app.write_audit(
    'tenant.work_task_transitioned',
    'work_task',
    v_task.id::text,
    v_tenant_id,
    jsonb_strip_nulls(jsonb_build_object(
      'previousStatus', v_task.status,
      'status', v_next_status,
      'previousDueAt', v_task.due_at,
      'nextDueAt', v_next_due_at,
      'note', v_clean_note,
      'taskUpdateMode', 'same_task_row_v3'
    ))
  );

  return jsonb_build_object(
    'id', v_task.id,
    'status', v_next_status,
    'dueAt', v_next_due_at,
    'previousDueAt', v_task.due_at,
    'completionTiming', v_completion_timing,
    'moved', v_next_due_at is distinct from v_task.due_at,
    'taskUpdateMode', 'same_task_row_v3'
  );
end;
$function$
